const fs = require('fs');
const path = require('path');

// ============================================================
// generar_460_aislar_mascotas.js
// ============================================================
// ARREGLO CRITICO — datos de una mascota apareciendo en otra.
//
// LA CAUSA
// ChiquiFlotante cargaba sus datos con useEffect(..., [oculto,
// pathname]). Cambiar de mascota NO cambia la ruta, asi que el efecto
// no se disparaba y el chat seguia con los datos de la anterior.
//
//   1. Abres Chiquito en el dashboard  -> carga datos de Chiquito
//   2. Cambias a Michi Proba           -> la ruta no cambia
//   3. El efecto no corre              -> los datos siguen siendo de Chiquito
//   4. Preguntas "¿cuanto pesa?"       -> responde 15 kg (de Chiquito)
//
// Las CONSULTAS estaban bien: todas filtran por mascota_id. El problema
// era CUANDO se ejecutaban.
//
// QUE SE ARREGLA
//
// 1. El chat sigue el id de la mascota activa y recarga cuando cambia.
//    localStorage no avisa en la misma pestaña, asi que se revisa cada
//    segundo y medio. Es una lectura de memoria: no cuesta nada y evita
//    tener que tocar el selector de mascotas.
//
// 2. Se BORRAN los datos antes de cargar los nuevos. Es preferible que
//    el chat no aparezca por un instante a que muestre lo de otra.
//
// 3. Se LIMPIA LA CONVERSACION al cambiar. El historial de Chiquito no
//    puede quedar en pantalla mientras se mira a Michi — alguien podria
//    leer esas respuestas creyendo que son del animal que tiene delante.
//
// 4. Se comprueba que la mascota activa pertenezca al usuario. El id
//    vive en localStorage y podria ser de otra cuenta si alguien cambio
//    de sesion en el mismo dispositivo.
//
// 5. Se agrega user_id a las consultas que solo dependian de RLS. Una
//    sola capa no basta para datos de salud.
//
// LO QUE NO ARREGLA: los otros bugs de la auditoria (clasificacion,
// periodos, consejos que rotan). Eso va aparte — este script hace UNA
// cosa, que es la que puede hacer daño.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destinoChat = path.join(process.cwd(), RUTA_CHAT);
const destinoFlot = path.join(process.cwd(), RUTA_FLOT);

for (const [r, d] of [[RUTA_CHAT, destinoChat], [RUTA_FLOT, destinoFlot]]) {
  if (!fs.existsSync(d)) {
    abortar('no se encontro ' + r + '. Corre primero los scripts 458 y 457.');
  }
}

const actualFlot = fs.readFileSync(destinoFlot, 'utf8');
if (actualFlot.includes('setInterval(revisar, 1500)')) {
  abortar('el aislamiento ya esta aplicado. Parece que este script ya se corrio.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

// --- El chat debe limpiar la conversacion al cambiar de mascota
for (const r of ["'use client'", 'export default function ChiquiChat', 'mascotaId?: string', 'setMensajes([])', 'idPrevio']) {
  if (!chat.includes(r)) {
    abortar('el chat nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
console.log('  OK  el chat limpia la conversacion al cambiar de mascota');

// --- El flotante debe seguir el id activo
for (const r of ["'use client'", 'export default function ChiquiFlotante', 'setInterval(revisar, 1500)',
                 'idActivo])', 'setDatos(null)', 'mascotaId: m.id',
                 'mascotas.some(x => x.id === m.id)']) {
  if (!flot.includes(r)) {
    abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
console.log('  OK  el flotante recarga al cambiar de mascota');

// --- TODAS las consultas tienen que filtrar por mascota_id
const queries = flot.match(/supabase\.from\('[a-z_]+'\)[\s\S]*?(?=,\n|\n\s*\])/g) || [];
const sinFiltro = queries.filter(q => !q.includes("eq('mascota_id'") && !q.includes("eq('user_id'"));
if (sinFiltro.length > 0) {
  abortar(sinFiltro.length + ' consulta(s) sin filtro de mascota ni de usuario. No se escribio nada.');
}
console.log('  OK  las ' + queries.length + ' consultas filtran por mascota');

fs.writeFileSync(destinoChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(destinoFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);

console.log('');
console.log('PRUEBALO ASI:');
console.log('  1. Abre una mascota y pregunta cuanto pesa.');
console.log('  2. Cambia a otra SIN salir de la pantalla.');
console.log('  3. Abre el chat: la conversacion debe estar vacia.');
console.log('  4. Pregunta el peso: debe responder el de la segunda.');
console.log('');
console.log('Listo. Cada mascota con sus propios datos.');
